"""
knowledge_extra.py - additional topics so that all 46 MediChat categories have real training
questions and curated responses (see taxonomy.py for the category mapping).

Same schema as knowledge.TOPICS. Every question, keyword and answer here is AUTHOR-WRITTEN
general health education - NOT real patient data and NOT clinician-reviewed. No medicine doses.
General sources the wording was based on (consult these to review/extend): WHO fact sheets
(who.int/news-room/fact-sheets), NHS health A-Z (nhs.uk/conditions), MedlinePlus (medlineplus.gov),
CDC (cdc.gov), Government of India Tele-MANAS (14416) and the national emergency number 112.

NOTE: this module must not import knowledge.py (knowledge.py imports this module).
"""

_CRISIS_LINES = ("Call 112 (India emergency number) or go to the nearest hospital now. You can also call "
                 "Tele-MANAS, the Government of India free 24x7 mental health helpline, on 14416 or "
                 "1800-891-4416. If you can, tell someone you trust and stay with them.")


def _t(id, category, questions, keywords, short, details, advice, doctor, urgent=False):
    return {"id": id, "category": category, "urgent": urgent, "questions": questions,
            "keywords": keywords, "short": short, "details": details, "advice": advice, "doctor": doctor}


